CREATE TRIGGER RefCusConditionCode_Version_Create
	ON RefCusConditionCode
	FOR INSERT
	AS
	INSERT RefDbVersionControl (RVC_ParentPK, RVC_ParentCode)
	SELECT ZY7_PK, 'ZY7'
	FROM inserted
GO
CREATE TRIGGER RefCusConditionCode_Version_Update
	ON RefCusConditionCode
	FOR Update
	AS
	UPDATE version SET RVC_IsPublished = 0, RVC_LastEditedUser = dbo.GetUserId()
	FROM RefDbVersionControl version
	JOIN inserted ON ZY7_PK = RVC_ParentPK
	WHERE RVC_IsPublished = 1
GO
